package com.aichangeguard.impact.database.model;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * A single evidence-backed finding generated by the Database Impact Analyzer.
 *
 * <p>Every finding carries:
 * <ul>
 *   <li>Precise severity classification (DESTRUCTIVE, POTENTIALLY_BREAKING, NON_BREAKING, INFORMATIONAL, UNKNOWN).</li>
 *   <li>Distinction between migration-based evidence and entity-inferred changes.</li>
 *   <li>Source file and line reference for traceability.</li>
 * </ul>
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record DatabaseChangeFinding(
        DatabaseChangeType changeType,
        DatabaseChangeSeverity severity,
        EvidenceCategory evidenceCategory,
        String title,
        String description,
        String affectedTable,
        String affectedColumn,
        String baseValue,
        String targetValue,
        String sourceFile,
        int sourceLine,
        String rawEvidence,
        String remediationHint
) {}

